import { ethers } from 'ethers';

// 四权类型定义
export type EchoRights = 'ownership' | 'usage' | 'derivative' | 'extension';

// 定价模型类型
export type PricingModelType = 'TimesBased' | 'DurationBased' | 'Subscription' | 'Freemium' | 'Hybrid';

export interface PricingModel {
  type: PricingModelType;
  pricePerUse?: bigint;
  pricePerMinute?: bigint;
  minMinutes?: number;
  pricePerMonth?: bigint;
  features?: string[];
  freeUses?: number;
  pricePerUseAfter?: bigint;
  base?: bigint;
  usage?: bigint;
  maxMonthly?: bigint;
}

// 衍生条款
export interface DerivativeTerms {
  upfrontFee: bigint;
  usageRoyalty: number; // 百分比
  approved: boolean;
}

// 扩展权授权
export interface ExtensionPermission {
  consumer: string; // 合约地址
  beneficiary: string; // 收益接收地址
  approved: boolean;
}

// ECHO 资产信息
export interface EchoAsset {
  id: string;
  tokenId: bigint;
  name: string;
  description: string;
  owner: string;
  image?: string;
  pricing: PricingModel;
  isExtensible: boolean;
  maxSceneRoyalty: number;
  derivativeTerms: DerivativeTerms;
  createdAt: number;
}

// 裁决结果类型
export type VerdictType = 'APPROVED' | 'DENIED' | 'CONDITIONAL' | 'PENDING_APPROVAL';

export interface ExecutionVerdict {
  verdict: VerdictType;
  requiredPayment?: bigint;
  message: string;
}

export interface CapabilityMatch {
  asset: EchoAsset;
  confidence: number;
  keywords: string[];
}

export interface RoutingResult {
  success: boolean;
  matched?: CapabilityMatch;
  estimatedCost?: bigint;
  verdict: ExecutionVerdict;
}

export interface SettlementPlan {
  type: 'immediate' | 'rental' | 'subscription';
  amount: bigint;
  breakdown: {
    creator: bigint;
    protocol: bigint;
    ecosystem: bigint;
    parentRoyalties?: bigint;
    sceneBeneficiary?: bigint;
  };
}

// 衍生关系
export interface DerivativeRelation {
  parentId: string;
  childId: string;
  approved: boolean;
  feePaid: bigint;
}

// 分润记录
export interface RevenueEvent {
  assetId: string;
  amount: bigint;
  timestamp: number;
  shares: {
    address: string;
    amount: bigint;
  }[];
}

// 执行历史
export interface ExecutionRecord {
  id: string;
  assetId: string;
  user: string;
  request: string;
  result: string;
  cost: bigint;
  timestamp: number;
  success: boolean;
}

// 统计数据
export interface EchoStats {
  totalAssets: number;
  totalExecutions: number;
  totalRevenue: bigint;
  activeUsers: number;
  recentExecutions: ExecutionRecord[];
  revenueHistory: { date: string; amount: number }[];
}

