export class EchoSimulatorService {
  private assets: EchoAsset[] = [...MOCK_ASSETS];
  private executions: ExecutionRecord[] = [];
  private revenues: RevenueEvent[] = [];
  private derivatives: DerivativeRelation[] = [];

  // 获取所有资产列表
  listAssets(): EchoAsset[] {
    return [...this.assets];
  }

  // 根据ID获取资产
  getAssetById(id: string): EchoAsset | undefined {
    return this.assets.find(a => a.id === id);
  }

  // 根据关键词搜索资产
  searchAssets(keywords: string): EchoAsset[] {
    const lower = keywords.toLowerCase();
    return this.assets.filter(a => 
      a.name.toLowerCase().includes(lower) || 
      a.description.toLowerCase().includes(lower)
    );
  }

  // 路由匹配 - 根据用户请求匹配最合适的能力
  routeRequest(request: string): RoutingResult {
    // 简单关键词匹配实现
    const keywords = request.toLowerCase().split(/\s+/).filter(k => k.length > 3);

    let bestMatch: {asset: EchoAsset; score: number; matches: string[]} | null = null;

    for (const asset of this.assets) {
      const assetKeywords = [...asset.name.toLowerCase().split(' '), ...asset.description.toLowerCase().split(' ')];
      const matches: string[] = [];

      for (const kw of keywords) {
        if (assetKeywords.some(ak => ak.includes(kw))) {
          matches.push(kw);
        }
      }

      const score = matches.length / Math.max(keywords.length, 1);

      if (!bestMatch || score > bestMatch.score) {
        bestMatch = { asset, score, matches };
      }
    }

    if (!bestMatch || bestMatch.score === 0) {
      return {
        success: false,
        verdict: {
          verdict: 'DENIED',
          message: 'No matching capability found'
        }
      };
    }

    const confidence = bestMatch.score;
    const asset = bestMatch.asset;

    // 计算价格
    let estimatedCost = BigInt(0);
    switch (asset.pricing.type) {
      case 'TimesBased':
        estimatedCost = asset.pricing.pricePerUse!;
        break;
      case 'Freemium':
        // 简单模拟：免费次数用完后收费
        const freeUses = asset.pricing.freeUses!;
        const userUses = this.countUserUses('current-user', asset.id);
        if (userUses >= freeUses) {
          estimatedCost = asset.pricing.pricePerUseAfter!;
        }
        break;
      default:
        estimatedCost = BigInt('10000000000000000'); // 默认 0.01 ETH
    }

    // 裁决
    const verdict = this.determineVerdict(asset, 'current-user');

    return {
      success: true,
      matched: {
        asset,
        confidence: confidence * 100,
        keywords: bestMatch.matches
      },
      estimatedCost,
      verdict
    };
  }

  // 权限裁决
  private determineVerdict(asset: EchoAsset, user: string): ExecutionVerdict {
    // 规则1: 所有者直接通过
    if (asset.owner === user) {
      return {
        verdict: 'APPROVED',
        message: 'Owner approved'
      };
    }

    // 简化规则：检查是否需要付费
    const pricing = asset.pricing;
    if (pricing.type === 'TimesBased' && pricing.pricePerUse! > BigInt(0)) {
      return {
        verdict: 'CONDITIONAL',
        requiredPayment: pricing.pricePerUse!,
        message: `Payment required: ${ethers.formatEther(pricing.pricePerUse!)} ETH`
      };
    }

    if (pricing.type === 'Freemium') {
      const userUses = this.countUserUses(user, asset.id);
      if (userUses >= pricing.freeUses!) {
        return {
          verdict: 'CONDITIONAL',
          requiredPayment: pricing.pricePerUseAfter!,
          message: `Free uses exhausted, payment required: ${ethers.formatEther(pricing.pricePerUseAfter!)} ETH`
        };
      }
    }

    return {
      verdict: 'APPROVED',
      message: 'Free usage approved'
    };
  }

  private countUserUses(user: string, assetId: string): number {
    return this.executions.filter(e => e.user === user && e.assetId === assetId).length;
  }

  // 计算分润计划
  calculateSettlement(asset: EchoAsset, amount: bigint): SettlementPlan {
    // ECHO 分润规则: 80% creator, 15% protocol, 5% ecosystem
    const creator = (amount * BigInt(80)) / BigInt(100);
    const protocol = (amount * BigInt(15)) / BigInt(100);
    const ecosystem = amount - creator - protocol;

    const plan: SettlementPlan = {
      type: 'immediate',
      amount,
      breakdown: {
        creator,
        protocol,
        ecosystem
      }
    };

    // 如果是衍生资产，还要加上父代版税
    const relation = this.derivatives.find(d => d.childId === asset.id);
    if (relation && asset.derivativeTerms.usageRoyalty > 0) {
      const royalty = (amount * BigInt(asset.derivativeTerms.usageRoyalty)) / BigInt(100);
      plan.breakdown.parentRoyalties = royalty;
      plan.breakdown.creator = plan.breakdown.creator - royalty;
    }

    return plan;
  }

  // 执行记录
  recordExecution(record: Omit<ExecutionRecord, 'id' | 'timestamp'>): ExecutionRecord {
    const newRecord: ExecutionRecord = {
      ...record,
      id: `exec-${this.executions.length + 1}`,
      timestamp: Date.now()
    };
    this.executions.push(newRecord);
    return newRecord;
  }

  // 记录分润
  recordRevenue(event: Omit<RevenueEvent, 'timestamp'>): RevenueEvent {
    const newEvent: RevenueEvent = {
      ...event,
      timestamp: Date.now()
    };
    this.revenues.push(newEvent);
    return newEvent;
  }

  // 获取统计数据
  getStats(): EchoStats {
    const now = new Date();
    const revenueHistory: EchoStats['revenueHistory'] = [];

    // 生成最近7天的模拟数据
    for (let i = 6; i >= 0; i--) {
      const date = new Date(now);
      date.setDate(date.getDate() - i);
      const dayStart = new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
      const dayEnd = dayStart + 24 * 60 * 60 * 1000;

      const dayRevenue = this.revenues
        .filter(r => r.timestamp >= dayStart && r.timestamp < dayEnd)
        .reduce((sum, r) => sum + parseFloat(ethers.formatEther(r.amount)), 0);

      revenueHistory.push({
        date: date.toLocaleDateString('en-US', {month: 'short', day: 'numeric'}),
        amount: dayRevenue
      });
    }

    const totalRevenue = this.revenues.reduce((sum, r) => sum + r.amount, BigInt(0));
    const uniqueUsers = new Set(this.executions.map(e => e.user));

    return {
      totalAssets: this.assets.length,
      totalExecutions: this.executions.length,
      totalRevenue,
      activeUsers: uniqueUsers.size,
      recentExecutions: this.executions.slice(-10).reverse(),
      revenueHistory
    };
  }

  // 获取执行历史
  getRecentExecutions(limit: number = 10): ExecutionRecord[] {
    return [...this.executions].reverse().slice(0, limit);
  }

  // 添加衍生关系
  addDerivativeRelation(relation: DerivativeRelation): void {
    this.derivatives.push(relation);
  }

  // 创建新资产 (模拟)
  createAsset(asset: Omit<EchoAsset, 'id' | 'createdAt'>): EchoAsset {
    const newAsset: EchoAsset = {
      ...asset,
      id: `echo-${this.assets.length + 1}`,
      createdAt: Date.now()
    };
    this.assets.push(newAsset);
    return newAsset;
  }
}

