import { useState, useCallback } from 'react';
import { ethers } from 'ethers';
import { agentEngine, ExecutionResult } from '../services/agentEngine';
import { RoutingResult, EchoAsset, EchoStats, ExecutionRecord } from '../types';

export function useEcho() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentRouting, setCurrentRouting] = useState<RoutingResult | null>(null);
  const [lastExecution, setLastExecution] = useState<ExecutionResult | null>(null);
  const [assets, setAssets] = useState<EchoAsset[]>([]);
  const [stats, setStats] = useState<EchoStats | null>(null);
  const [recentExecutions, setRecentExecutions] = useState<ExecutionRecord[]>([]);

  // 加载资产列表
  const loadAssets = useCallback(() => {
    try {
      const list = agentEngine.listAssets();
      setAssets(list);
      return list;
    } catch (err: any) {
      setError(err.message);
      return [];
    }
  }, []);

  // 搜索资产
  const searchAssets = useCallback((keyword: string) => {
    try {
      const results = agentEngine.searchAssets(keyword);
      setAssets(results);
      return results;
    } catch (err: any) {
      setError(err.message);
      return [];
    }
  }, []);

  // 路由请求
  const routeRequest = useCallback((userRequest: string): RoutingResult => {
    setLoading(true);
    setError(null);
    try {
      const result = agentEngine.routeRequest(userRequest);
      setCurrentRouting(result);
      return result;
    } catch (err: any) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  // 执行能力
  const executeCapability = useCallback(async (
    request: string, 
    routing: RoutingResult,
    userAddress?: string
  ): Promise<ExecutionResult> => {
    setLoading(true);
    setError(null);
    try {
      const result = await agentEngine.executeCapability(request, routing, userAddress);
      setLastExecution(result);
      // 刷新执行记录
      loadRecentExecutions();
      loadStats();
      return result;
    } catch (err: any) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  // 加载统计数据
  const loadStats = useCallback(() => {
    try {
      const data = agentEngine.getStats();
      setStats(data);
      return data;
    } catch (err: any) {
      setError(err.message);
      return null;
    }
  }, []);

  // 加载最近执行
  const loadRecentExecutions = useCallback((limit?: number) => {
    try {
      const records = agentEngine.getRecentExecutions(limit);
      setRecentExecutions(records);
      return records;
    } catch (err: any) {
      setError(err.message);
      return [];
    }
  }, []);

  // 格式化金额
  const formatEther = (amount: bigint): string => {
    return parseFloat(ethers.formatEther(amount)).toFixed(4);
  };

  return {
    loading,
    error,
    currentRouting,
    lastExecution,
    assets,
    stats,
    recentExecutions,
    loadAssets,
    searchAssets,
    routeRequest,
    executeCapability,
    loadStats,
    loadRecentExecutions,
    formatEther
  };
}

