        <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
        {shortAddress}
      </span>
      <button 
        onClick={onDisconnect}
        className="btn-secondary text-sm"
      >
        Disconnect
      </button>
    </div>
  );
}

