import React, { useState } from 'react';
import { Send, CheckCircle, XCircle, AlertCircle, DollarSign } from 'lucide-react';
import { useEcho } from '../../../hooks/useEcho';
import { RoutingResult, SettlementPlan } from '../../../types';
import { ethers } from 'ethers';

export function AgentExecutor() {
  const [request, setRequest] = useState('');
  const { 
    loading, 
    currentRouting, 
    lastExecution, 
    error, 
    routeRequest, 
    executeCapability,
    formatEther
  } = useEcho();

  const handleRoute = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!request.trim()) return;
    routeRequest(request.trim());
  };

  const handleExecute = async () => {
    if (!currentRouting?.success) return;
    await executeCapability(request, currentRouting);
  };

  const getVerdictBadge = (verdict: string) => {
    switch (verdict) {
      case 'APPROVED':
        return (
          <span className="inline-flex items-center gap-1 px-3 py-1 bg-green-100 text-green-800 rounded-full text-sm">
            <CheckCircle size={14} /> APPROVED
          </span>
        );
      case 'DENIED':
        return (
          <span className="inline-flex items-center gap-1 px-3 py-1 bg-red-100 text-red-800 rounded-full text-sm">
            <XCircle size={14} /> DENIED
          </span>
        );
      case 'CONDITIONAL':
        return (
          <span className="inline-flex items-center gap-1 px-3 py-1 bg-yellow-100 text-yellow-800 rounded-full text-sm">
            <DollarSign size={14} /> PAYMENT REQUIRED
          </span>
        );
      default:
        return (
          <span className="inline-flex items-center gap-1 px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm">
            <AlertCircle size={14} /> PENDING
          </span>
        );
    }
  };

  const renderSettlement = (settlement: SettlementPlan) => {
    return (
      <div className="mt-4 p-4 bg-gray-50 rounded-lg border border-gray-200">
        <h4 className="font-semibold mb-2">Settlement Breakdown</h4>
        <div className="space-y-2 text-sm">
          {Object.entries(settlement.breakdown).map(([name, amount]) => {
            if (amount === undefined || amount === BigInt(0)) return null;
            return (
              <div key={name} className="flex justify-between">
                <span className="capitalize text-gray-600">{name}:</span>
                <span className="font-medium">{formatEther(amount)} ETH</span>
              </div>
            );
          })}
          <div className="pt-2 border-t border-gray-200 flex justify-between font-semibold">
            <span>Total:</span>
            <span>{formatEther(settlement.amount)} ETH</span>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold mb-2">Agent Executor</h2>
        <p className="text-gray-600">
          输入你的请求，系统将自动匹配最合适的 AI Agent 能力，进行权限裁决，并执行调用，费用自动分润。
        </p>
      </div>

      {/* Request Form */}
      <div className="card">
        <form onSubmit={handleRoute} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Enter your request:
            </label>
            <textarea
              value={request}
              onChange={(e) => setRequest(e.target.value)}
              placeholder="例: 帮我分析这份合同有没有法律风险"
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-primary-500 focus:border-transparent outline-none min-h-[100px]"
            />
          </div>
          <button 
            type="submit"
            disabled={loading || !request.trim()}
            className="btn-primary flex items-center gap-2"
          >
            {loading ? 'Routing...' : 'Route & Find Capability'}
            {!loading && <Send size={16} />}
          </button>
        </form>
      </div>

      {/* Error */}
      {error && (
        <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      {/* Routing Result */}
      {currentRouting && (
        <div className="card">
          <h3 className="text-lg font-semibold mb-4">Routing Result</h3>

          {currentRouting.success && currentRouting.matched && (
            <>
              <div className="grid md:grid-cols-2 gap-4 mb-4">
                <div className="p-4 bg-gray-50 rounded-lg">
                  <p className="text-sm text-gray-600 mb-1">Matched Asset</p>
                  <p className="text-xl font-bold">{currentRouting.matched.asset.name}</p>
                  <p className="text-sm text-gray-500 mt-1">
                    {currentRouting.matched.asset.description}
                  </p>
                </div>
                <div className="p-4 bg-gray-50 rounded-lg">
                  <p className="text-sm text-gray-600 mb-1">Confidence</p>
                  <div className="w-full bg-gray-200 rounded-full h-3 mt-4 mb-2">
                    <div 
                      className="bg-primary-500 h-3 rounded-full" 
                      style={{ width: `${currentRouting.matched.confidence}%` }}
                    ></div>
                  </div>
                  <p className="text-right text-sm font-medium">
                    {currentRouting.matched.confidence.toFixed(1)}%
                  </p>
                </div>
              </div>

              <div className="mb-4">
                <p className="text-sm text-gray-600 mb-2">Permission Verdict:</p>
                <div className="flex items-center gap-2">
                  {getVerdictBadge(currentRouting.verdict.verdict)}
                  <span className="text-gray-600 text-sm">{currentRouting.verdict.message}</span>
                </div>
              </div>

              {currentRouting.estimatedCost && currentRouting.estimatedCost > BigInt(0) && (
                <div className="mb-4 p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
                  <p className="flex items-center justify-between">
                    <span className="text-yellow-800">Estimated Cost:</span>
                    <span className="font-bold text-yellow-800">
                      {formatEther(currentRouting.estimatedCost)} ETH
                    </span>
                  </p>
                </div>
              )}

              {currentRouting.verdict.verdict === 'APPROVED' || 
               currentRouting.verdict.verdict === 'CONDITIONAL' ? (
                <button 
                  onClick={handleExecute}
                  disabled={loading}
                  className="btn-primary w-full"
                >
                  {loading ? 'Executing...' : 'Execute Capability'}
                </button>
              ) : null}
            </>
          )}

          {!currentRouting.success && (
            <div className="p-4 bg-red-50 border border-red-200 rounded-lg">
              <p className="text-red-700">No matching capability found. Please try a different request.</p>
              <p className="text-sm text-red-600 mt-1">
                Verdict: {currentRouting.verdict.message}
              </p>
            </div>
          )}
        </div>
      )}

      {/* Execution Result */}
      {lastExecution?.output && (
        <div className="card">
          <h3 className="text-lg font-semibold mb-4">Execution Output</h3>
          <div className="p-4 bg-gray-900 text-gray-100 rounded-lg whitespace-pre-line font-mono text-sm leading-relaxed">
            {lastExecution.output}
          </div>
          {lastExecution.settlement && renderSettlement(lastExecution.settlement)}
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { Search, Box, DollarSign, Tag, Lock, Unlock } from 'lucide-react';
import { useEcho } from '../../../hooks/useEcho';
import { EchoAsset } from '../../../types';

interface AssetMarketProps {
  onAssetSelect?: (asset: EchoAsset) => void;
}

export function AssetMarket({ onAssetSelect }: AssetMarketProps) {
  const [search, setSearch] = useState('');
  const { assets, loadAssets, searchAssets, formatEther } = useEcho();

  useEffect(() => {
    if (search) {
      searchAssets(search);
    } else {
      loadAssets();
    }
  }, [search, loadAssets, searchAssets]);

  useEffect(() => {
    loadAssets();
  }, [loadAssets]);

  const getPricingText = (asset: EchoAsset): string => {
    const { pricing } = asset;
    switch (pricing.type) {
      case 'TimesBased':
        return `${formatEther(pricing.pricePerUse!)} ETH / use`;
      case 'DurationBased':
        return `${formatEther(pricing.pricePerMinute!)} ETH / min (min ${pricing.minMinutes} min)`;
      case 'Subscription':
        return `${formatEther(pricing.pricePerMonth!)} ETH / month`;
      case 'Freemium':
        return `${pricing.freeUses} free, ${formatEther(pricing.pricePerUseAfter!)} ETH after`;
      case 'Hybrid':
        return `${formatEther(pricing.base!)} base + ${formatEther(pricing.usage!)} usage`;
      default:
        return 'Custom pricing';
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold mb-2">Asset Market</h2>
        <p className="text-gray-600">
          Browse registered ECHO AI capability assets, search and filter by keywords.
        </p>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
        <input
          type="text"
          placeholder="Search assets by name or description..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="w-full pl-10 pr-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-primary-500 focus:border-transparent outline-none"
        />
      </div>

      {/* Asset Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {assets.map((asset) => (
          <div 
            key={asset.id}
            className="card hover:border-primary-300 transition-colors cursor-pointer"
            onClick={() => onAssetSelect?.(asset)}
          >
            <div className="flex items-start justify-between mb-3">
              <div className="flex items-center gap-2">
                <Box size={18} className="text-primary-500" />
                <h3 className="font-semibold text-lg">{asset.name}</h3>
              </div>
            </div>

            <p className="text-gray-600 text-sm mb-4 line-clamp-2">
              {asset.description}
            </p>

            <div className="space-y-2 text-sm">
              <div className="flex items-center justify-between">
                <span className="flex items-center gap-1 text-gray-600">
                  <DollarSign size={14} /> Pricing
                </span>
                <span className="font-medium">{getPricingText(asset)}</span>
              </div>

              <div className="flex items-center justify-between">
                <span className="text-gray-600">Extensible</span>
                {asset.isExtensible ? (
                  <span className="flex items-center gap-1 text-green-600">
                    <Unlock size={14} /> Yes
                  </span>
                ) : (
                  <span className="flex items-center gap-1 text-gray-500">
                    <Lock size={14} /> No
                  </span>
                )}
              </div>

              {asset.derivativeTerms.approved && (
                <div className="flex items-center justify-between">
                  <span className="text-gray-600">Derivative Royalty</span>
                  <span className="font-medium">{asset.derivativeTerms.usageRoyalty}%</span>
                </div>
              )}
            </div>

            <div className="mt-4 pt-3 border-t border-gray-100">
              <span className="text-xs text-gray-500">
                Owner: {asset.owner.slice(0, 8)}...
              </span>
            </div>
          </div>
        ))}
      </div>

      {assets.length === 0 && (
        <div className="text-center py-12 text-gray-500">
          <Box size={48} className="mx-auto mb-4 opacity-50" />
          <p>No assets found matching your search.</p>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { GitBranch, Plus, Check, X, Clock } from 'lucide-react';
import { useEcho } from '../../../hooks/useEcho';
import { EchoAsset } from '../../../types';

interface DerivativeRelation {
  parentId: string;
  childId: string;
  approved: boolean;
  feePaid: bigint;
}

export function DerivativeManager() {
  const { assets, loadAssets, formatEther } = useEcho();
  const [relations, setRelations] = useState<DerivativeRelation[]>([
    {
      parentId: 'echo-001',
      childId: 'echo-005',
      approved: true,
      feePaid: BigInt('10000000000000000000') // 10 ETH
    }
  ]);

  const [pendingRequests, setPendingRequests] = useState<{
    parentId: string;
    requester: string;
    timestamp: number;
  }[]>([
    {
      parentId: 'echo-002',
      requester: '0xRequester1',
      timestamp: Date.now() - 2 * 24 * 60 * 60 * 1000
    }
  ]);

  useEffect(() => {
    loadAssets();
  }, [loadAssets]);

  const getAssetById = (id: string): EchoAsset | undefined => {
    return assets.find(a => a.id === id);
  };

  const approveRequest = (index: number) => {
    const newPending = [...pendingRequests];
    newPending.splice(index, 1);
    setPendingRequests(newPending);
    // In a real implementation, this would call the contract
  };

  const rejectRequest = (index: number) => {
    const newPending = [...pendingRequests];
    newPending.splice(index, 1);
    setPendingRequests(newPending);
    // In a real implementation, this would call the contract
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold mb-2 flex items-center gap-2">
          <GitBranch size={24} /> Derivative Manager
        </h2>
        <p className="text-gray-600">
          管理衍生权请求，查看衍生资产图谱，追踪衍生关系分润。
        </p>
      </div>

      <div className="card">
        <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <Clock size={18} />
          Pending Derivative Requests
        </h3>
        {pendingRequests.length === 0 ? (
          <p className="text-gray-500 italic">No pending requests.</p>
        ) : (
          <div className="space-y-4">
            {pendingRequests.map((req, idx) => {
              const asset = getAssetById(req.parentId);
              return (
                <div key={idx} className="p-4 border border-yellow-200 bg-yellow-50 rounded-lg">
                  <div className="flex items-start justify-between">
                    <div>
                      <p className="font-medium">
                        Parent Asset: {asset?.name || req.parentId}
                      </p>
                      <p className="text-sm text-gray-600">
                        Requester: {req.requester.slice(0, 10)}...
                      </p>
                      <p className="text-sm text-gray-500">
                        Requested: {new Date(req.timestamp).toLocaleString()}
                      </p>
                    </div>
                    <div className="flex gap-2">
                      <button 
                        onClick={() => approveRequest(idx)}
                        className="px-3 py-1 bg-green-500 hover:bg-green-600 text-white rounded-lg text-sm flex items-center gap-1"
                      >
                        <Check size={14} /> Approve
                      </button>
                      <button 
                        onClick={() => rejectRequest(idx)}
                        className="px-3 py-1 bg-red-500 hover:bg-red-600 text-white rounded-lg text-sm flex items-center gap-1"
                      >
                        <X size={14} /> Reject
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div className="card">
        <h3 className="text-lg font-semibold mb-4">Existing Derivative Relations</h3>
