import React, {useState} from 'react';
import { Share2, Check, X, Edit } from 'lucide-react';

interface Permission {
  consumer: string;
  beneficiary: string;
  approved: boolean;
}

export function ExtensionRights() {
  const [permissions, setPermissions] = useState<Permission[]>([
    {
      consumer: '0xTelegramBotContract',
      beneficiary: '0xPlatformOwner',
      approved: true
    },
    {
      consumer: '0xDiscordBotContract',
      beneficiary: '0xPlatformOwner',
      approved: false
    }
  ]);

  const [pendingRequests, setPendingRequests] = useState<{
    consumer: string;
    beneficiary: string;
    timestamp: number;
  }[]>([
    {
      consumer: '0xWebPortal',
      beneficiary: '0xWebOwner',
      timestamp: Date.now() - 24 * 60 * 60 * 1000
    }
  ]);

  const toggleApproval = (index: number) => {
    const newPermissions = [...permissions];
    newPermissions[index].approved = !newPermissions[index].approved;
    setPermissions(newPermissions);
  };

  const updateBeneficiary = (index: number, newBeneficiary: string) => {
    const newPermissions = [...permissions];
    newPermissions[index].beneficiary = newBeneficiary;
    setPermissions(newPermissions);
  };

  const approveRequest = (index: number) => {
    const req = pendingRequests[index];
    setPermissions([...permissions, { ...req, approved: true }]);
    const newPending = [...pendingRequests];
    newPending.splice(index, 1);
    setPendingRequests(newPending);
  };

  const rejectRequest = (index: number) => {
    const newPending = [...pendingRequests];
    newPending.splice(index, 1);
    setPendingRequests(newPending);
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold mb-2 flex items-center gap-2">
          <Share2 size={24} /> Extension Rights
        </h2>
        <p className="text-gray-600">
          管理扩展权授权，允许第三方平台/场景使用你的 AI 能力，并获得场景分润。
        </p>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        {/* OwnerDirect 模式 */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4">OwnerDirect 授权模式</h3>
          <p className="text-sm text-gray-600 mb-4">
            资产所有者直接批准或吊销第三方扩展权
          </p>
          <div className="space-y-3">
            {permissions.map((perm, idx) => (
              <div key={idx} className="p-3 border border-gray-200 rounded-lg">
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <p className="text-sm text-gray-600">Consumer Contract:</p>
                    <p className="font-mono text-sm">{perm.consumer.slice(0, 16)}...</p>
                  </div>
                  <button
                    onClick={() => toggleApproval(idx)}
                    className={`px-2 py-1 rounded-full text-xs font-medium ${
                      perm.approved 
                        ? 'bg-green-100 text-green-800' 
                        : 'bg-gray-100 text-gray-800'
                    }`}
                  >
                    {perm.approved ? (
                      <><Check size={12} className="inline mr-1" /> Approved</>
                    ) : (
                      <>Revoked</>
                    )}
                  </button>
                </div>
                <div>
                  <p className="text-sm text-gray-600 mb-1">Scene Beneficiary:</p>
                  <div className="flex items-center gap-2">
                    <input 
                      type="text" 
                      value={perm.beneficiary}
                      onChange={(e) => updateBeneficiary(idx, e.target.value)}
                      className="flex-1 px-2 py-1 text-sm border border-gray-300 rounded"
                    />
                    <Edit size={16} className="text-gray-400" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* RequestBased 模式 */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4">RequestBased 模式</h3>
          <p className="text-sm text-gray-600 mb-4">
            第三方发起扩展权申请，所有者手动批准或拒绝
          </p>
          <h4 className="font-medium mb-3">Pending Requests</h4>
          {pendingRequests.length === 0 ? (
            <p className="text-gray-500 italic text-sm">No pending requests.</p>
          ) : (
            <div className="space-y-3">
              {pendingRequests.map((req, idx) => (
                <div key={idx} className="p-3 border border-yellow-200 bg-yellow-50 rounded-lg">
                  <div className="mb-2">
                    <p className="text-sm text-gray-600">Consumer:</p>
                    <p className="font-mono text-sm">{req.consumer.slice(0, 16)}...</p>
                  </div>
                  <div className="mb-3">
                    <p className="text-sm text-gray-600">Beneficiary:</p>
                    <p className="font-mono text-sm">{req.beneficiary.slice(0, 16)}...</p>
                  </div>
                  <div className="flex justify-end gap-2">
                    <button 
                      onClick={() => rejectRequest(idx)}
                      className="px-3 py-1 bg-gray-200 hover:bg-gray-300 rounded text-sm"
                    >
                      <X size={14} className="inline mr-1" /> Reject
                    </button>
                    <button 
                      onClick={() => approveRequest(idx)}
                      className="px-3 py-1 bg-green-500 hover:bg-green-600 text-white rounded text-sm"
                    >
                      <Check size={14} className="inline mr-1" /> Approve
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="card">
        <h3 className="text-lg font-semibold mb-4">扩展权使用和分润</h3>
        <div className="space-y-4 text-gray-700">
          <ol className="list-decimal list-inside space-y-2">
            <li>第三方消费者合约申请扩展权</li>
            <li>资产所有者批准（或预先直接授权）</li>
            <li>用户在第三方场景调用能力</li>
            <li>用户支付调用费用</li>
            <li>按照协议分配收益：
              <ul className="list-disc list-inside ml-4 mt-1 space-y-1 text-sm text-gray-600">
                <li>资产所有者: 75%</li>
                <li>场景受益人: 15%</li>
                <li>协议层: 10%</li>
              </ul>
            </li>
          </ol>
          <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
            <p className="text-blue-800 text-sm">
              <strong>应用场景:</strong> 平台型应用可以集成第三方 ECHO 资产能力，用户付费后平台自动获得分润，不需要手动结算。
              创作者可以将自己的能力授权给多个平台使用，每个平台每次使用都会自动给创作者付费。
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

