import React, { useState } from 'react';
import { 
  LayoutDashboard, 
  Play, 
  Gavel, 
  DollarSign, 
  GitBranch, 
  Share2, 
  Code,
  Store
} from 'lucide-react';
import { Header } from '../common/Header';
import { Dashboard } from './Dashboard';
import { AgentExecutor } from './AgentExecutor';
import { PermissionArbiter } from './PermissionArbiter';
import { BillingSettlement } from './BillingSettlement';
import { DerivativeManager } from './DerivativeManager';
import { ExtensionRights } from './ExtensionRights';
import { AssetMarket } from './AssetMarket';
import { EchoContracts } from './EchoContracts';
import { useWallet } from '../../../hooks/useWallet';

type ViewType = 
  | 'dashboard' 
  | 'agent-executor' 
  | 'permission-arbiter' 
  | 'billing-settlement'
  | 'derivative-manager'
  | 'extension-rights'
  | 'asset-market'
  | 'echo-contracts';

interface MenuItem {
  id: ViewType;
  label: string;
  icon: React.ElementType;
}

const MENU_ITEMS: MenuItem[] = [
  { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { id: 'asset-market', label: 'Asset Market', icon: Store },
  { id: 'agent-executor', label: 'Agent Executor', icon: Play },
  { id: 'permission-arbiter', label: 'Permission Arbiter', icon: Gavel },
  { id: 'billing-settlement', label: 'Billing & Settlement', icon: DollarSign },
  { id: 'derivative-manager', label: 'Derivative Manager', icon: GitBranch },
  { id: 'extension-rights', label: 'Extension Rights', icon: Share2 },
  { id: 'echo-contracts', label: 'ECHO Contracts', icon: Code },
];

export function EchoNexusHub() {
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const { 
    address, 
    isConnected, 
    isConnecting, 
    connect, 
    disconnect,
    hasProvider
  } = useWallet();

  const renderView = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard onSelectView={setCurrentView} />;
      case 'asset-market':
        return <AssetMarket />;
      case 'agent-executor':
        return <AgentExecutor />;
      case 'permission-arbiter':
        return <PermissionArbiter />;
      case 'billing-settlement':
        return <BillingSettlement />;
      case 'derivative-manager':
        return <DerivativeManager />;
      case 'extension-rights':
        return <ExtensionRights />;
      case 'echo-contracts':
        return <EchoContracts />;
      default:
        return <Dashboard onSelectView={setCurrentView} />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <Header 
        connected={isConnected}
        address={address}
        isConnecting={isConnecting}
        onConnect={connect}
        onDisconnect={disconnect}
      />

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <aside className="hidden lg:block w-64 bg-white border-r border-gray-200 flex-shrink-0">
          <nav className="p-4 space-y-1">
            {MENU_ITEMS.map((item) => {
              const Icon = item.icon;
              const isActive = currentView === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => setCurrentView(item.id)}
                  className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg transition-colors text-left ${
                    isActive 
                      ? 'bg-primary-50 text-primary-600' 
                      : 'text-gray-700 hover:bg-gray-100'
                  }`}
                >
                  <Icon size={18} />
                  <span className="font-medium">{item.label}</span>
                </button>
              );
            })}
          </nav>
        </aside>

        {/* Mobile Bottom Navigation */}
        <div className="lg:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 z-40">
          <div className="grid grid-cols-4 gap-1 p-1">
            {MENU_ITEMS.slice(0, 4).map((item) => {
              const Icon = item.icon;
              const isActive = currentView === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => setCurrentView(item.id)}
                  className={`flex flex-col items-center gap-1 px-1 py-2 rounded-md ${
                    isActive ? 'text-primary-600 bg-primary-50' : 'text-gray-600'
                  }`}
                >
                  <Icon size={18} />
                  <span className="text-xs">{item.label.split(' ')[0]}</span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Main Content */}
        <main className="flex-1 overflow-y-auto p-4 lg:p-6 pb-20 lg:pb-6">
          <div className="container mx-auto max-w-6xl">
            {!hasProvider && (
              <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                <p className="text-yellow-800">
                  🦊 No MetaMask detected. You can still explore the demo in simulation mode, 
                  but you won't be able to connect to the actual blockchain.
                </p>
              </div>
            )}
            {renderView()}
          </div>
        </main>
      </div>
    </div>
  );
}

import React from 'react';
import { EchoNexusHub } from './components/hub/EchoNexusHub';

function App() {
  return <EchoNexusHub />;
}

export default App;

